<form method="post" class="grid-two"><?= csrf_field() ?><input type="hidden" name="idempotency_key" value="<?= esc($key,'attr') ?>"><section class="panel"><h2>ที่อยู่จัดส่ง</h2><div class="stack"><label>ชื่อผู้รับ<input name="recipient" value="<?= esc($user['name'],'attr') ?>" required maxlength="120"></label><label>เบอร์โทร<input name="phone" value="<?= esc($user['phone'],'attr') ?>" required minlength="3" maxlength="40"></label><label>ที่อยู่พร้อมรหัสไปรษณีย์<textarea name="address" required maxlength="1000"></textarea></label><label>โค้ดโปรโมชั่น<input name="coupon" maxlength="32" placeholder="ถ้ามี"></label></div></section><section class="panel"><h2>สรุปคำสั่งซื้อ</h2><?= view('platform/order_pv',['items'=>$quote['items']]) ?><?php foreach($quote['items'] as $p): ?><p><?= esc($p['name']) ?> × <?= $p['quantity'] ?><?php if(!empty($p['discount_satang'])): ?><br><del><?= p_money($p['original_price_satang']*$p['quantity']) ?></del><br><small class="sn-cart-discount">ลด <?= esc(\App\Libraries\Platform\ProductPricing::discountLabel($p)) ?> ต่อชิ้น</small><?php endif ?><br><strong><?= p_money($p['price_satang']*$p['quantity']) ?></strong></p><?php endforeach ?><hr><p>ยอดสินค้า <?= p_money($quote['subtotal']) ?></p><p>ค่าจัดส่ง <?= p_money($quote['shipping']) ?></p><p class="price">รวมก่อนโปรโมชั่น <?= p_money($quote['total']) ?></p><p class="muted">ระบบตรวจโค้ดโปรโมชั่นและคำนวณยอดสุทธิเมื่อยืนยันคำสั่งซื้อ</p><button>ยืนยันสั่งซื้อ</button></section></form>
